CREATE OR REPLACE FUNCTION public.atualizavfornecedores()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare

  vpessoatipo char;

  vpessoanumero varchar(14);

  vcnpj varchar(14);

  vinscricaomunicipal varchar(20);

  vtipo char;

  vinscrest fornecedores.inscricaoestadual%TYPE;

  vfoneramal varchar(10);

  vempddd    int2;

  vempfone integer;

  vempramal char(10);

  vempresa varchar(40);

  vgrupofornecedor integer;

  vcivil char(1);

  vmarkup numeric(8,2);

  vconjuge integer;

  vconceito int2;

  vcodigo bigint;

  venderecoalterado date;

  vnome varchar;

  vrazao varchar(60);

  vemail varchar(128);

  vnosimples boolean;
  
  vestrangeiro boolean;

  vsexo varchar(1);

  vhistoricocontabil integer;

begin



  if TG_RELNAME = 'clientes' then

    vtipo := 'C';

    if TG_OP <> 'DELETE' then

      vpessoanumero      := new.pessoanumero;

	  vinscricaomunicipal:= new.inscricaomunicipal;

      vpessoatipo        := new.pessoatipo;

      vinscrest          := new.iddocumento;

      vfoneramal         := new.foneramal;

      vempfone           := new.empfonenumero;

      vempddd            := new.empfoneddd;

      vempramal          := new.empfoneramal;

      vempresa           := new.empresa;

      vcivil             := new.civil;

      vconjuge           := new.conjuge;

      vconceito          := new.conceito;

      venderecoalterado  := new.enderecoalterado;

      vnome              := (case when btrim(coalesce(new.apelido,''))<>'' then new.apelido else new.nome end);

      vrazao             := new.nome;

      vemail             := new.email;

      vnosimples         := new.nosimples;
	  
	  vestrangeiro       := new.estrangeiro;

      vmarkup            := new.markup;

      vsexo              := new.sexo;

      vhistoricocontabil := new.historicocontabil;	

    end if;

  else

    vcivil := 'O';

    if TG_RELNAME = 'fornecedores' then

      vtipo  := 'F';

      if TG_OP <> 'DELETE' then

        vpessoanumero      := new.pessoanumero;

		vinscricaomunicipal:= new.inscricaomunicipal;

        vpessoatipo        := new.pessoatipo;

        vinscrest          := new.inscricaoestadual;

        vempfone           := new.faxnumero;

        vempddd            := new.faxddd;

        vgrupofornecedor   := new.grupofornecedor;

        vmarkup            := new.markup;

        vconceito          := new.conceito;

        venderecoalterado  := new.enderecoalterado;

        vnome              := (case when btrim(coalesce(new.nome,''))<>'' then new.nome else new.razao end);

        vrazao             := new.razao;

        vemail             := new.email;

        vnosimples         := new.nosimples;
		
		vestrangeiro       := new.estrangeiro;

        vsexo              := 'E';

        vhistoricocontabil := new.historicocontabil;

      end if;

    else

      if TG_RELNAME = 'filiais' then

        vtipo  := 'L';

        if TG_OP <> 'DELETE' then

          vpessoanumero     := new.cnpj;

		  vinscricaomunicipal:= new.inscricaomunicipal;

          vpessoatipo       := 'J';

          vinscrest         := new.inscricaoestadual;

          vempfone          := new.faxnumero;

          vempddd           := new.faxddd;

          vnome             := new.razao;

          vrazao            := new.razao;

          vemail            := null;

          vnosimples        := false;
		  
		  vestrangeiro      := false;

          vsexo              := 'E';

          vhistoricocontabil := null;

        end if;

      end if;

    end if;

  end if;



  if TG_OP = 'INSERT' then

    if (vpessoanumero <> '') AND (vpessoanumero <> '0') then

           vcnpj:= cast(substring(vpessoanumero from 1 for length(vpessoanumero)-2) as varchar);

      else vcnpj:= '';

    end if;

    insert into vfornecedores (codigo,

                               nome,

			       razao,

                               pessoatipo,

                               pessoanumero,

                               cnpj,

                               inscricaoestadual,

                               rua,

                               numero,

                               complemento,

                               cidade,

                               bairro,

                               cep,

                               estado,

                               tipo,

                               fonenumero,

                               foneddd,

                               foneramal,

                               fonenumeroempresa,

                               fonedddempresa,

                               foneramalempresa,

                               empresa,

                               grupofornecedor,

                               civil,

                               markup,

                               conjuge,

                               conceito,

			       enderecoalterado,

			       email,

			       debito,

			       credito,

			       nosimples,
				   
				   estrangeiro,

			       contribicms,

      	       sexo,

	             suframa,

	             historicocontabil,

				 inscricaomunicipal

                )



    values (new.codigo,

            vnome,

	    vrazao,

            vpessoatipo,

            vpessoanumero,

            vcnpj,

            vinscrest,

            new.rua,

            new.numero,

            new.complemento,

            new.cidade,

            new.bairro,

            new.cep,

            new.estado,

            vtipo,

            new.fonenumero,

            new.foneddd,

            vfoneramal,

            vempfone,

            vempddd,

            vempramal,

            vempresa,

            vgrupofornecedor,

            vcivil,

            vmarkup,

            vconjuge,

            vconceito,

	    venderecoalterado,

	    vemail,

	    new.debito,

	    new.credito,

	    vnosimples,
		
		vestrangeiro,

	    new.contribicms,

       vsexo,

       new.suframa,

       vhistoricocontabil,

	   vinscricaomunicipal

	    );

  else

    vcodigo := old.codigo;

    if TG_OP = 'DELETE' then

      if TG_RELNAME = 'clientes' then

        delete from vfornecedores where codigo = old.codigo and tipo = 'C';

      else

        if TG_RELNAME = 'fornecedores' then

          delete from vfornecedores where codigo = old.codigo and tipo = 'F';

        else

          if TG_RELNAME = 'filiais' then

            delete from vfornecedores where codigo = old.codigo and tipo = 'L';

          end if;

        end if;

      end if;

    else

      if TG_OP = 'UPDATE' then

        if (vpessoanumero <> '') and (vpessoanumero <> '0') then

               vcnpj:= cast(substring(vpessoanumero from 1 for length(vpessoanumero)-2) as varchar);

          else vcnpj:= '';

        end if;





        update vfornecedores set nome              = vnome,

	                         razao             = vrazao,

                                 pessoatipo        = vpessoatipo,

                                 pessoanumero      = vpessoanumero,

                                 cnpj              = vcnpj,

                                 inscricaoestadual = vinscrest,

                                 rua               = new.rua,

                                 numero            = new.numero,

                                 complemento       = new.complemento,

                                 cidade            = new.cidade,

                                 bairro            = new.bairro,

                                 cep               = new.cep,

                                 estado            = new.estado,

                                 fonenumero        = new.fonenumero,

                                 foneddd           = new.foneddd,

                                 foneramal         = vfoneramal,

                                 fonenumeroempresa = vempfone,

                                 fonedddempresa    = vempddd,

                                 foneramalempresa  = vempramal,

                                 empresa           = vempresa,

                                 grupofornecedor   = vgrupofornecedor,

                                 civil             = vcivil,

                                 markup            = vmarkup,

                                 conjuge           = vconjuge,

                                 conceito          = vconceito,

                                 enderecoalterado  = venderecoalterado,

                                 email             = vemail,

                                 debito            = new.debito,

                                 credito           = new.credito,

                                 nosimples         = vnosimples,
								 
								 estrangeiro       = vestrangeiro,

                                 contribicms       = new.contribicms,

                                 sexo              = vsexo,

                                 suframa           = new.suframa,

                                 historicocontabil = vhistoricocontabil,

								 inscricaomunicipal = vinscricaomunicipal

        where codigo = vcodigo and tipo = vtipo;

      end if;

    end if;

  end if;

  return new;

end;
$function$

CREATE OR REPLACE FUNCTION public.autenticacoes_antesinseriratualizar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE

   vAnterior RECORD;

   

   SeqMovtoBanco INTEGER;

   SeqMovtoBancoEvento INTEGER;

   vEvento   INT2;

   vSaida    BOOLEAN;

   vSaldo    NUMERIC;

   vOrigemSaldoAnterior INTEGER;

   vTipo     CHAR;

   vValor    NUMERIC;

   vConta    INTEGER;

   vJuros    NUMERIC;

   vParcelas RECORD;

   vErro     BOOLEAN;

   vTransacao INTEGER;

   vDocumentoPag integer;

   vNumeroDuplicata integer;

   vOrigemLancto char(2);

   vObservacoes VARCHAR(1000);

   vFornecedor VARCHAR(60);

   /*vHoraInicial timestamp;

   vTempoTranscorrido time;

   */

   vcount integer;



BEGIN





   IF TG_OP = 'INSERT' AND NEW.Tipo = 'C' ------------------------ Para evitar o cancelamento de uma

   THEN                                                         -- autentica��o mais de uma vez

        IF EXISTS (SELECT Numero

                      FROM Autenticacoes

                      WHERE Autenticacao = NEW.Autenticacao)

        THEN RAISE EXCEPTION 'A autentica��o j� havia sido cancelada anteriormente.';

        END IF;

   END IF;



   

   IF TG_OP = 'INSERT' AND NEW.Tipo = 'P' --------------------------------- Inser��o de [P]resta��o?

   THEN

        ----------------------------------------------- J� existe a parcela do contrato autenticada,

                                                     -- sem que ela tenha sido cancelada?

        IF EXISTS (SELECT a1.ContratoParcela, Parcela

                      FROM Autenticacoes a1

                      WHERE a1.Tipo            = 'P'                                  -- [P]resta��o

                        AND a1.ContratoParcela = NEW.ContratoParcela

                        AND a1.Parcela         = NEW.Parcela

                        AND NOT EXISTS (SELECT a2.Autenticacao

                                          FROM autenticacoes a2

                                          WHERE a2.Tipo   = 'C'                    -- [C]ancelamento

                                            AND a1.Numero = a2.Autenticacao))

        THEN RAISE EXCEPTION 'Opera��o inv�lida na quita��o da parcela % do contrato %: J� existe uma autentica��o desta parcela!',

                             NEW.Parcela, NEW.ContratoParcela;

        END IF;

        

        -------------------------------------------------- � uma quita��o e a tabela parcelas n�o esta quitada?  N�o permitir esta situa��o (situa��o de erro no Teclux)

        

        if     new.tipo = 'P' 

           and coalesce(new.situacao,false)

           and new.contratoparcela is not null

           and new.parcela is not null

           and not coalesce(new.cancelada,false)

           and new.transacao is not null

        then

          if not exists (select p.contrato, p.numero

                         from parcelas p 

                         where p.contrato = new.contratoparcela

                           and p.numero = new.parcela

                           and p.datapagto is not null and p.datapagto = new.data

                           and p.valorpagto is not null and p.valorpagto = new.valor

                           and p.transacao is not null and p.transacao = new.transacao)

          THEN RAISE EXCEPTION 'Opera��o inv�lida na quita��o da parcela % do contrato %: A quita��o da tabela parcela n�o foi encontrada!',

                                  NEW.Parcela, NEW.ContratoParcela;



          end if;           

                                            

        end if;

           

   END IF;



   IF TG_OP = 'INSERT' AND NOT new.alterandoevento

   THEN IF EXISTS (SELECT Numero

                      FROM Autenticacoes

                      WHERE Caixa  = NEW.Caixa  AND

                            Filial = NEW.Filial AND

                            CAST(Data    ::VARCHAR || ' ' || Hora    ::VARCHAR AS TIMESTAMP) >

                            CAST(NEW.Data::VARCHAR || ' ' || NEW.Hora::VARCHAR AS TIMESTAMP))

        THEN RAISE EXCEPTION

                         'Opera��o inv�lida na opera��o do caixa - verifique o hor�rio do servidor';

        END IF;

   END IF;





   IF NOT NEW.AlterandoEvento

   THEN IF NEW.Numero IS NULL

        THEN NEW.Numero:= Autenticacoes_ProximoNumero();

        END  IF;



        --------------------------------------------------------------- Acesso � �ltima autentica��o        

        

        /*

        IF TG_OP = 'INSERT' then

            vHoraInicial := (select (timeofday()::timestamp));



            loop

        

                  if (select coalesce(controle,false) from autenticacoesaux limit 1) then

                    exit;

                  end if;

            

                  vTempoTranscorrido :=  (select (timeofday()::timestamp)) - vHoraInicial;

                

                  if vTempoTranscorrido > cast('00:01:00' as time) then

                    exit;

                  end if;                                    

            

            end loop;

            

            LOCK TABLE autenticacoesaux IN ACCESS EXCLUSIVE MODE;

            update autenticacoesaux set controle = false;

                        

        end if;

        */

        

        SELECT Data, Hora, Saldo, transacao, numero INTO vAnterior

           FROM Autenticacoes

           WHERE Numero = (SELECT Numero

                              FROM Autenticacoes

                              WHERE Filial = NEW.Filial AND Caixa = NEW.Caixa

                              and data_hora_tz(data,hora)=(select max(data_hora_tz(a1.data,a1.hora)) from autenticacoes a1 where caixa=NEW.Caixa and filial=NEW.Filial)

                              ORDER BY data desc, hora desc, numero desc limit 1);

                            

        vSaldo:= 0;

        vOrigemSaldoAnterior := null;

        

        

        IF FOUND

        THEN IF  (CAST(NEW.Data::VARCHAR || ' ' || NEW.Hora::VARCHAR AS TIMESTAMP) <

                  CAST(vAnterior.Data::VARCHAR || ' ' || vAnterior.Hora::VARCHAR AS TIMESTAMP)) and                

--                 (NEW.Transacao <> vAnterior.transacao) and

                  (TG_OP = 'INSERT') and

                 NEW.Tipo <> 'S'                                         -- [S]a�da por transfer�ncia

             THEN RAISE EXCEPTION 'N�o � poss�vel realizar opera��o retroativa (% - %)',

                                  CAST(vAnterior.Data::VARCHAR || ' ' || vAnterior.Hora::VARCHAR AS TIMESTAMP),

                                  CAST(NEW.Data::VARCHAR || ' ' || NEW.Hora::VARCHAR AS TIMESTAMP);

             END IF;

                          

             

             vSaldo := COALESCE(vAnterior.Saldo, 0);

             vOrigemSaldoAnterior := vAnterior.numero;

             

             

        END IF;





        IF TG_OP = 'UPDATE'

        THEN IF OLD.Tipo = 'S'          AND -------------------------- Era [S]a�da por transfer�ncia

                OLD.Confirmacao IS NULL AND                         -- n�o  confirmada  e  que  est�

                NEW.Confirmacao = TRUE                              -- sendo confirmada

             THEN 

             

               /* inicio Contratolar concorr�ncias 

               loop

                          

                 if vOrigemSaldoAnterior is not null then

                 

                   if not exists (SELECT a.numero

                                  FROM Autenticacoes a

                                  WHERE a.origemsaldoanterior = vOrigemSaldoAnterior) then

                     exit;

                     

                   else

                   

                    SELECT Data, Hora, Saldo, transacao, numero INTO vAnterior

                       FROM Autenticacoes

                       WHERE Numero = (SELECT Numero

                                          FROM Autenticacoes

                                          WHERE Filial = NEW.Filial AND Caixa = NEW.Caixa

                                          ORDER BY data desc, hora desc, numero desc limit 1);

                                          

                      vSaldo := COALESCE(vAnterior.Saldo, 0);

                    vOrigemSaldoAnterior := vAnterior.numero;



                   

                   end if;

                   

                 else

                 

                    SELECT Data, Hora, Saldo, transacao, numero INTO vAnterior

                       FROM Autenticacoes

                       WHERE Numero = (SELECT Numero

                                          FROM Autenticacoes

                                          WHERE Filial = NEW.Filial AND Caixa = NEW.Caixa

                                          ORDER BY data desc, hora desc, numero desc limit 1);

                                          

                      vSaldo := COALESCE(vAnterior.Saldo, 0);

                    vOrigemSaldoAnterior := vAnterior.numero;

                    

                    if vOrigemSaldoAnterior is null then

                      exit;

                    end if ;

                    

                 end if;                          

                 

               end loop;      

                fim Contratolar concorr�ncias */

           

               NEW.Saldo := vSaldo - OLD.Valor;

/*               NEW.OrigemSaldoAnterior := vOrigemSaldoAnterior; */

               

             END IF;



             ----------------------------------------------------- Se for [D]ocumento, verifica se o

        ELSE vSaida:= TRUE;                                          -- evento � de Sa�da ou Entrada

             IF NEW.Tipo = 'D'

             THEN SELECT COALESCE((TipoMovimentacao IN ('S',                      -- [S]a�da

                                                        'T')),                    -- [T]ransfer�ncia

                                                               FALSE) INTO vSaida

                     FROM Eventos

                     WHERE Codigo = NEW.Evento;



                  IF NOT FOUND

                  THEN RAISE EXCEPTION 'O evento % n�o foi encontrado', NEW.Evento;

                  END IF;

             END IF;



             ------------------------------------------------- Sendo [C]ancelamento, busca-se o tipo

             IF NEW.Tipo = 'C'                              -- de autentica��o que foi cancelada

             THEN SELECT Tipo INTO vTipo

                     FROM Autenticacoes

                     WHERE Numero = NEW.Autenticacao;



                  IF FOUND

                  THEN IF vTipo = 'D'                                                 -- [D]ocumento

                       THEN SELECT Evento INTO vEvento

                               FROM Autenticacoes

                               WHERE Numero = NEW.Autenticacao;



                            IF NOT FOUND

                            THEN RAISE EXCEPTION 'A autentica��o % n�o foi encontrada', NEW.Autenticacao;

                            END IF;



                            SELECT NOT COALESCE((TipoMovimentacao IN ('S',        -- [S]a�da

                                                                      'T')),      -- [T]ransfer�ncia

                                                                             FALSE) INTO vSaida

                               FROM Eventos

                               WHERE Codigo = vEvento;



                            IF NOT FOUND

                            THEN RAISE EXCEPTION 'O evento % n�o foi encontrado', vEvento;

                            END IF;



                       ELSE IF vTipo = 'F'                                      -- [F]rente de caixa

                            THEN SELECT Transacao INTO vTransacao

                                    FROM Autenticacoes

                                    WHERE Numero = NEW.Autenticacao;



                                    IF FOUND

                                    THEN UPDATE Recebimentos

                                            SET Situacao  = 'C',

                                                Conta     = NULL,

                                                Sequencia = NULL

                                            WHERE Transacao = vTransacao;

                                    END IF;



                            ELSE vSaida:= vTipo IN ('E',              -- [E]ntrada por transfer�ncia

                                            --        'F',              -- [F]rente de caixa

                                                    'P',              -- [P]resta��o

                                                    'R',              -- [R]esgate de cheque
													'U');             -- [U] Devolu��o Cart�o/PIX/Cheque famoso...n�o esta em caixa     

                            END IF;

                       END IF;



                       UPDATE Autenticacoes

                          SET Cancelada = TRUE,

                              Situacao  = FALSE

                          WHERE Numero = NEW.Autenticacao;



                  ELSE RAISE EXCEPTION 'A autentica��o % n�o foi encontrada', NEW.Autenticacao;

                  END IF;

             END IF;



             /* inicio Contratolar concorr�ncias */

              loop

                          

                 if vOrigemSaldoAnterior is not null then

                 

                   if not exists (SELECT a.numero

                                  FROM Autenticacoes a

                                  WHERE a.origemsaldoanterior = vOrigemSaldoAnterior) then

                     exit;

                     

                   else

                   

                    SELECT Data, Hora, Saldo, transacao, numero INTO vAnterior

                       FROM Autenticacoes

                       WHERE Numero = (SELECT Numero

                                          FROM Autenticacoes

                                          WHERE Filial = NEW.Filial AND Caixa = NEW.Caixa

                                          and data_hora_tz(data,hora)=(select max(data_hora_tz(a1.data,a1.hora)) from autenticacoes a1 where a1.caixa=NEW.Caixa and a1.filial=NEW.Filial)

                                          ORDER BY data desc, hora desc, numero desc limit 1);

                                          

                      vSaldo := COALESCE(vAnterior.Saldo, 0);

                    vOrigemSaldoAnterior := vAnterior.numero;



                   

                   end if;

                   

                 else

                 

                    SELECT Data, Hora, Saldo, transacao, numero INTO vAnterior

                       FROM Autenticacoes

                       WHERE Numero = (SELECT Numero

                                          FROM Autenticacoes

                                          WHERE Filial = NEW.Filial AND Caixa = NEW.Caixa

                                          and data_hora_tz(data,hora)=(select max(data_hora_tz(a1.data,a1.hora)) from autenticacoes a1 where a1.caixa=NEW.Caixa and a1.filial=NEW.Filial)

                                          ORDER BY data desc, hora desc, numero desc limit 1);

                                          

                      vSaldo := COALESCE(vAnterior.Saldo, 0);

                    vOrigemSaldoAnterior := vAnterior.numero;

                    

                    if vOrigemSaldoAnterior is null then

                      exit;

                    end if ;

                    

                 end if;                          

                 

             end loop;      

             /* fim Contratolar concorr�ncias */

             

             --------------------------------------------------------- ATUALIZA��O DO SALDO DO CAIXA

             IF NEW.Tipo IN ('J')                                     -- Perdas [J]udiciais

             THEN 

             

               NEW.Saldo:= vSaldo;

               NEW.OrigemSaldoAnterior := vOrigemSaldoAnterior;

               

             ELSE IF NEW.Tipo IN ('E',                                -- [E]ntrada por transfer�ncia
                                  'F',                                -- [F]rente de caixa
                                  'P',                                -- [P]resta��o
                                  'R',                                -- [R]esgate de cheque
								  'U')                                -- Entrada pela devolu��o de Cart�o (d�bito ou cr�dito), Cheques e PIX ...Famoso n�o tem em "caixa"

                  THEN 

                    --caso contrato tenha sido cancelado mas j� estava selecionado no caixa, acaba quitando a parcela, mesmo contrato j� estando cancelado. COLOCADO PARA EVITAR

                    IF NEW.tipo='P' and not exists (SELECT numero FROM contratos WHERE numero=NEW.contratoparcela AND situacao IN ('F','P','N')) THEN

                     RAISE EXCEPTION 'SITUACAO DO CONTRATO FOI ALTERADA, FAVOR VERIFICAR';

                    END IF;

                  

                    NEW.Saldo:= vSaldo + NEW.Valor;

                    NEW.OrigemSaldoAnterior := vOrigemSaldoAnterior;

                  ELSE IF NEW.Tipo = 'C' AND                          -- [C]ancelamento

                          vTipo IN  ('J',                             -- Perdas [J]udiciais

                                     'S')                             -- [S]a�da por transfer�ncia

                       THEN 

                         NEW.Saldo:= vSaldo;

                         NEW.OrigemSaldoAnterior := vOrigemSaldoAnterior;

                       ELSE IF NOT vSaida AND NEW.Tipo IN ('C',       -- [C]ancelamento

                                                           'D')       -- [D]ocumento

                            THEN 

                              NEW.Saldo:= vSaldo + NEW.Valor;

                              NEW.OrigemSaldoAnterior := vOrigemSaldoAnterior;

                            ELSE IF NEW.Tipo = 'S'                    -- [S]a�da por transfer�ncia

                                 THEN 

                                   NEW.Saldo:= vSaldo;

                                   NEW.OrigemSaldoAnterior := vOrigemSaldoAnterior;

                                 ELSE 

                                   NEW.Saldo:= vSaldo - NEW.Valor;                   -- [H] Cheque  [N] Devolu��o
                                   NEW.OrigemSaldoAnterior := vOrigemSaldoAnterior;  -- [T]Cart�es D�bito/Cr�dito

                                 END IF;

                            END IF;

                       END IF;

                  END IF;

             END IF;

             

             

        END IF;

   END IF;

   NEW.AlterandoEvento:= False;



   

   ----------------------------------------------------------------------------- INTEGRA��O BANC�RIA

   SELECT ContaCaixa INTO vConta                                -- A filial est� integrada a bancos?

      FROM Filiais

      WHERE Codigo = NEW.Filial;



   ----------------------------------------------------------- Lan�amento ap�s a data de integra��o?

   IF FOUND AND vConta IS NOT NULL             AND

      '1980-01-01' <> InicioIntegracaoBancos() AND

      NEW.Data     >= InicioIntegracaoBancos() AND



      NOT (NEW.Tipo IN ('C',    -- [C]ancelamento

                        'H',    -- C[H]eque

                        'T',    -- Car[T]]ao

                        'G'))   -- Contas a pa[G]ar



   THEN vDocumentoPag   := NULL;

        vNumeroDuplicata:= NULL;

        vOrigemLancto   := 'X';   -- Cai[X]a

        vEvento         := NULL;



        vJuros:= 0;

           IF NEW.Tipo = 'A' THEN vEvento:= 501;                          -- S[A]ldo de Troca

        ELSIF NEW.Tipo = 'B' THEN vEvento:= NEW.Evento;                   -- Dep�sito [B]anc�rio

        ELSIF NEW.Tipo = 'D' THEN vEvento:= NEW.Evento;                   -- [D]ocumento

