CREATE OR REPLACE FUNCTION public.contratos_antesinserir()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
     vRenegociado  BOOLEAN;
 begin
   IF (TG_OP = 'INSERT') THEN
   
      /*PARA VENDAS DO SITE*/
      IF (COALESCE(NEW.desconto,0)>0) and 
         (COALESCE(NEW.descontofinanceiro,0)+COALESCE(NEW.descontogeral,0)=0) AND
         exists (select contrato from pedidos_site p_s where p_s.contrato = new.numero) THEN
         NEW.descontofinanceiro=NEW.desconto;
      END IF;

     IF NEW.origem IS NOT NULL THEN
        SELECT origem IS NOT NULL INTO vRenegociado
           FROM contratos
           WHERE contratos.origem = NEW.origem;
        
        IF (vRenegociado IS NOT NULL) AND vRenegociado THEN
           RAISE EXCEPTION 'Renegocia��o n�o permitida para o contrato (%) renegociado',NEW.origem;
        END IF;
        
     END IF;
    
     IF new.numero is null then
       new.numero := contratos_proximonumero();
     END IF;
    
   ELSE
     IF (TG_OP = 'UPDATE') THEN
           
       IF ((NEW.situacao = 'R') AND ((OLD.situacao IN ('F','N','P','C')) AND (COALESCE(NEW.OPERACAO,'')<>'C'))) THEN
         RAISE EXCEPTION 'Problemas na atualiza��o do contrato "%", Sit. anterior: "%" atual: "%". Entre em contato com o suporte!',new.numero,old.situacao,new.situacao;         
       ELSEIF ((NEW.situacao = 'O') AND ((OLD.situacao IN ('R','F','N','P','C')) AND (COALESCE(NEW.OPERACAO,'')<>'C'))) THEN
         RAISE EXCEPTION 'Problemas na atualiza��o do contrato "%", Sit. anterior: "%" atual: "%". Entre em contato com o suporte!',new.numero,old.situacao,new.situacao;        
       ELSEIF OLD.SITUACAO='N' AND NEW.SITUACAO IN ('F','P') AND not produtos_pendentes(new.numero) THEN
         RAISE EXCEPTION 'Problemas na atualiza��o do contrato "%", Sit. anterior: "%" atual: "%". Entre em contato com o suporte!',new.numero,old.situacao,new.situacao;        
       ELSEIF ((NEW.situacao = 'R') AND (OLD.situacao = 'O')) THEN
         if NEW.datareservado is null then
           NEW.datareservado = current_date;
         end if;
       ELSEIF ((NEW.situacao='R') AND (OLD.situacao IN ('F','N','P') AND (COALESCE(NEW.OPERACAO,'')='C'))) THEN
         NEW.faturamento=NULL;
         NEW.operacao=NULL;
       ELSEIF ((NEW.situacao='F' OR NEW.situacao='N' OR NEW.situacao='P') AND OLD.situacao IN ('O','R') AND (NEW.faturamento IS NULL)) THEN
         if NEW.faturamento is null then
           NEW.faturamento = current_date;
         end if;  
         /*
       ELSEIF NEW.situacao='C' THEN  
         update atendimentos set status = 'F' where contrato = new.numero and exists (select ap.atendimento from atendimentosprodutos ap where ap.atendimento = atendimentos.codigo);
        */ 
       END IF;
       
       NEW.operacao=NULL;
    
     END IF;
    
   END IF;

   IF TG_OP='UPDATE' THEN
       IF ((NEW.SITUACAO IN ('N','P')) OR (OLD.SITUACAO<>'R' AND NEW.SITUACAO='F'))
          and coalesce(new.creditotroca,0) <> 0
          and exists (select p.contrato
                      from parcelas p
                      where p.contrato = new.numero
                        and p.formapagamento = 'T'
                        and (p.datapagto is null or coalesce(p.valorpagto,0)=0) limit 1)
        THEN
            RAISE EXCEPTION 'O contrato % possui parcelas com pagamento em cr�dito de troca sem data ou valor de pagamento. Entre em contato com o suporte da tecSOFT.', new.numero;    
        END IF;                 
        
    END IF;
    
    RETURN NEW;
    
 end;
$function$

CREATE OR REPLACE FUNCTION public.contratosdatransacao(integer)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
  vTransacao ALIAS FOR $1;
  vParcelas	RECORD;
  vLista	VARCHAR;
BEGIN
  vLista := '';
  FOR vParcelas IN SELECT distinct p.contrato FROM parcelas p WHERE p.transacao = vTransacao order by p.contrato
  LOOP
	vLista := vLista||', '||vParcelas.contrato;
  END LOOP;
  RETURN substr(vLista,3);
END;
$function$

CREATE OR REPLACE FUNCTION public.filiais_log()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    diffs jsonb := '{}'::jsonb;
    field text;
    old_row jsonb;
    new_row jsonb;
BEGIN
    IF (TG_OP = 'UPDATE') THEN
        old_row := to_jsonb(OLD);
        new_row := to_jsonb(NEW);

        FOR field IN SELECT column_name FROM information_schema.columns
                     WHERE table_name = 'filiais'
        LOOP
            IF new_row -> field IS DISTINCT FROM old_row -> field THEN
                diffs := diffs || jsonb_build_object(field, jsonb_build_object(
                    'old', old_row -> field,
                    'new', new_row -> field
                ));
            END IF;
        END LOOP;

        IF diffs <> '{}'::jsonb THEN
            INSERT INTO filiais_log (
                codigo, trigger_mode, trigger_user, trigger_changed, trigger_tuple, dados
            ) VALUES (
                NEW.codigo, TG_OP, current_user, now(), 'diff', diffs
            );
        END IF;

    ELSIF (TG_OP = 'DELETE') THEN
        INSERT INTO filiais_log (
            codigo, trigger_mode, trigger_user, trigger_changed, trigger_tuple, dados
        ) VALUES (
            OLD.codigo, TG_OP, current_user, now(), 'old', to_jsonb(OLD)
        );

    ELSIF (TG_OP = 'INSERT') THEN
        INSERT INTO filiais_log (
            codigo, trigger_mode, trigger_user, trigger_changed, trigger_tuple, dados
        ) VALUES (
            NEW.codigo, TG_OP, current_user, now(), 'new', to_jsonb(NEW)
        );
    END IF;

    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.movtosbancoseventos_antesinseriratualizar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
   vContas        RECORD;
   vContasTransf  RECORD;
   vMovtosBancos  RECORD;
   vEventos       RECORD;
   vCreditar      INTEGER;
   vDebitar       INTEGER;
   vExercicio     INTEGER;
   vGerarContabil BOOLEAN;
   vLancamento    VARCHAR;
   vNrOrigem      BIGINT;
   vContrapartida INTEGER;
   vHistorico     INTEGER;
BEGIN
   SELECT * INTO vContas
      FROM  Contas
      WHERE Conta = NEW.Conta FOR UPDATE;

   IF NOT FOUND THEN
      RAISE EXCEPTION 'A conta corrente % n�o foi encontrada', NEW.Conta;
   ELSE
      new.sequenciaconta := vContas.sequenciaconta;    
   END IF;

   --------------------------------------------------------- Que tipo de evento?
   
   SELECT * INTO vEventos
      FROM  Eventos
      WHERE Codigo = NEW.Evento;
   
   IF NOT FOUND THEN
      RAISE EXCEPTION 'O evento "%" n�o foi encontrado', NEW.Evento;
   END IF;

   vHistorico:= vEventos.historicocontabil;
   
   -- Nas triggers das autentica�es o tipo n�o � informado.
   -- Nas triggers das autentica�es o evento � informado.
   IF NEW.tipo is null THEN
     IF vEventos.tipomovimentacao = 'S' THEN
       NEW.Tipo := 'S';
     ELSE
       IF vEventos.tipomovimentacao = 'E' THEN       
         NEW.Tipo := 'E'; 
       ELSE
         IF vEventos.tipomovimentacao = 'T' THEN       
           NEW.Tipo := 'T'; 
         END IF;	   
--       ELSE
--         RAISE EXCEPTION 'O evento "%" por autentica��o n�o pode ser do tipo Transfer�ncia', NEW.Evento;
       END IF; 
     END IF;

   END IF;
   
   IF NEW.Tipo = 'S' THEN ---------------- Sa�da
      NEW.Valor:= -ABS(NEW.Valor);
   ELSE 
     IF NEW.Tipo = 'E' THEN ------------------ Entrada
       NEW.Valor:=  ABS(NEW.Valor); 
     ELSE
       IF NEW.Tipo = 'T' THEN
          IF NEW.sequenciaorigem IS NULL THEN
            NEW.Valor:= -ABS(NEW.Valor);  -- � saida da transfer�ncia que gerou a entrada
          ELSE
            NEW.Valor:=  ABS(NEW.Valor);  -- � entrada da transfer�ncia gerada             
          END IF;
       END IF;  
     END IF;
   END IF;   
   
   if new.sequenciaevento is null then
      new.sequenciaevento := coalesce((select max(mbe.sequenciaevento)
                              from movtosbancoseventos mbe
                              where mbe.conta = new.conta
                                and mbe.data = new.data
                                and mbe.sequencia = new.sequencia
                                and mbe.evento = new.evento),0)+1;
   end if;
   
   SELECT * INTO vMovtosBancos
      FROM  MovtosBancos
      where MovtosBancos.Conta     = new.conta
        and MovtosBancos.Data      = new.Data 
        and MovtosBancos.Sequencia = new.Sequencia;
   ------------------------------------------ H� gera��o cont�bil e o lan�amento
					  -- tem origem em [B]ancos?
   IF new.sequenciaorigem is null and 
      vMovtosBancos.OrigemLancto = 'B' AND
      vContas.ContaContabil  IS NOT NULL AND
      vContas.Filial         IS NOT NULL AND 
      GerarContabilidade()  
   THEN
      vExercicio     := EXTRACT(Year FROM NEW.Data);
      IF new.tipo = 'T' THEN
        SELECT * INTO vContasTransf
          FROM Contas
         WHERE Conta = NEW.Contatransf FOR UPDATE;   
        vcontrapartida := vContasTransf.contacontabil;
      ELSE
        vcontrapartida := vEventos.Conta;
      END IF;

      vGerarContabil := vcontrapartida is not null;

      IF not vGerarContabil AND TG_OP = 'UPDATE'
      THEN vGerarContabil:= EXISTS (SELECT NrLancto
                                       FROM Lancamentos
                                       WHERE Filial    = vContas.Filial AND
                                             Exercicio = vExercicio     AND
                                             Data      = OLD.Data       AND
                                             Origem    = 'B'            AND
                                             NrOrigem = cast(to_char(old.data,'YY')||EXTRACT(DOY FROM old.data)||
                                                              cast((cast('10000000' as bigint) * cast(old.Conta as bigint)) as varchar) as bigint) + 
                                                         cast(10000 as bigint) * cast(old.Sequencia as bigint)+
                                                         cast(coalesce(old.evento,0) as bigint));
      END IF;

      IF vGerarContabil THEN 
         IF NEW.Tipo in ('S','T')             -- Sa�da
         THEN 
              vCreditar:= NULL;
              vDebitar := vcontrapartida;
         ELSE vCreditar:= vcontrapartida;     -- Entrada
              vDebitar := NULL;              
         END IF;

         vNrOrigem:= cast(to_char(new.data,'YY')||EXTRACT(DOY FROM new.data)||
                           cast((cast('10000000' as bigint) * cast(NEW.Conta as bigint)) as varchar) as bigint) + 
                      cast(10000 as bigint) * cast(NEW.Sequencia as bigint)+
                      cast(coalesce(NEW.evento,0) as bigint);

         IF TG_OP = 'INSERT' THEN
           IF NEW.valor = vMovtosBancos.valor then
             IF NEW.Tipo in ('S','T') THEN 
               update lancamentos set debitar = vDebitar,
                                      complemento = new.observacoes
               where Filial = vContas.Filial and
                     Exercicio = vExercicio and
                     Data      = new.data and
                     Origem    = 'B' and
                     NrOrigem  = vNrOrigem;
             ELSE
               update lancamentos set creditar = vCreditar,
                                      complemento = new.observacoes
               where Filial = vContas.Filial and
                     Exercicio = vExercicio and
                     Data      = new.data and
                     Origem    = 'B' and
                     NrOrigem  = vNrOrigem;
             END IF;
           ELSE

             INSERT INTO Lancamentos (Exercicio, NrLancto,  Filial,  Data,
                                      Origem,    NrOrigem,  Debitar, Creditar,
                                      Valor,     Historico, Complemento)

                    VALUES (vExercicio, NULL, vContas.Filial, NEW.Data,
                            'B', vNrOrigem, vDebitar, vCreditar,
                            ABS(NEW.Valor), vHistorico, new.Observacoes);
           END IF;
         END IF;

         IF TG_OP = 'UPDATE' THEN
            IF NEW.valor <> vMovtosBancos.valor then
              INSERT INTO procedenciatrigger (procedencia) values ('BANCOS'); 			
              DELETE FROM Lancamentos
                 WHERE Filial    = vContas.Filial AND
                       Exercicio = vExercicio     AND
                       Data      = OLD.Data       AND
                       Origem    = 'B'            AND
                       NrOrigem = cast(to_char(old.data,'YY')||EXTRACT(DOY FROM old.data)||
                                        cast((cast('10000000' as bigint) * cast(old.Conta as bigint)) as varchar) as bigint) + 
                                   cast(10000 as bigint) * cast(old.Sequencia as bigint)+
                                   cast(coalesce(old.evento,0) as bigint);
			  delete from procedenciatrigger where procedencia = 'BANCOS';		  					   
            END IF; 

            ------------------------------------ Nas atualiza�es,  OLD pode ter
                                              -- gerado lan�amento cont�bil, mas
            IF vcontrapartida IS NOT NULL     -- NEW n�o gerar�.
            THEN 

               IF NEW.valor = vMovtosBancos.valor then
                 IF NEW.Tipo in ('S','T') THEN 
                   update lancamentos set debitar = vDebitar,
                                          complemento = new.observacoes
                   where Filial = vContas.Filial and
                         Exercicio = vExercicio and
                         Data      = new.data and
                         Origem    = 'B' and
                         NrOrigem  = vNrOrigem;
                 ELSE
                   update lancamentos set creditar = vCreditar,
                                          complemento = new.observacoes
                   where Filial = vContas.Filial and
                         Exercicio = vExercicio and
                         Data      = new.data and
                         Origem    = 'B' and
                         NrOrigem  = vNrOrigem;
                 END IF;

               ELSE
 
                 INSERT INTO Lancamentos (Exercicio, NrLancto,  Filial,  Data,
                                          Origem,    NrOrigem,  Debitar, Creditar,
                                          Valor,     Historico, Complemento)
     
                        VALUES (vExercicio, NULL, vContas.Filial, NEW.Data,
                                'B', vNrOrigem, vDebitar, vCreditar,
                                ABS(NEW.Valor), vHistorico, new.Observacoes);             
               END IF;
            END IF;
         END IF;
      END IF;
   END IF;

   RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.orcamentosdatransacao(integer)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
  vTransacao ALIAS FOR $1;
  vParcelas	RECORD;
  vLista	VARCHAR;
BEGIN
  vLista := '';
  FOR vParcelas IN (select distinct o.codigo from orcamentos o where o.contrato in (SELECT distinct p.contrato FROM parcelas p WHERE p.transacao = vTransacao order by p.contrato))
  LOOP
	vLista := vLista||', '||vParcelas.codigo;
  END LOOP;
  RETURN substr(vLista,3);
END;
$function$

